API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Routing_and_SSL_Termination, "Routing & SSL Termination", "Azure Front Door / Azure Application Gateway", "Secures ingress, terminates SSL, and routes hybrid boundary traffic.")
    Component(Authentication_and_Authorization_Component, "Authentication & Authorization Component", "Azure Active Directory / OpenID Connect", "Validates incoming tokens and implements centralized Single Sign-On.")
    Component(Token_Exchange_and_Transformation, "Token Exchange & Transformation", "Internal Gateway Service", "Transforms and passes validated requests internally.")
}

Rel(Routing_and_SSL_Termination, Authentication_and_Authorization_Component, "Validates incoming tokens", "HTTPS / OIDC")
Rel(Routing_and_SSL_Termination, Token_Exchange_and_Transformation, "Passes validated requests", "Internal HTTP/2")

@enduml

Integration Layer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Integration_Layer", "Integration Layer") {
    Component(Routing_Mediator, "Routing Mediator", "Apache Camel", "Routes claim events and orchestrates message flow within the integration layer.")
    Component(Protocol_Translator, "Protocol Translator", "Java / Apache Camel", "Transforms payloads and maps canonical events to legacy schemas.")
    Component(Idempotency_Replay_Manager, "Idempotency & Replay Manager", "Azure Redis Cache", "Provides state storage for idempotency, ensuring zero data loss during nightly batch windows.")
    Component(Mainframe_ACL, "Mainframe ACL", "Integration Layer / Mainframe ACL", "Anti-Corruption Layer that interfaces directly with the legacy mainframe system.")
}

Rel(Routing_Mediator, Protocol_Translator, "Transforms payload for legacy", "In-memory Camel EIP")
Rel(Protocol_Translator, Mainframe_ACL, "Maps canonical events to legacy schemas", "Java / Apache Camel")

@enduml
